// Fonts for the voucher PDF (base64 TTF). Bodoni Moda, Anton, Space Mono: the site's own fonts (SIL OFL).
// Liberation Serif Italic (SIL OFL) is the fallback for Cyrillic text. Regenerate with scripts/pdf-fonts.py.
const b64 = (s: string) => Uint8Array.from(atob(s), (c) => c.charCodeAt(0));
export const fonts = {
  anton: b64(''),
  bodoni: b64(''),
  bodoniItalic: b64(''),
  mono: b64(''),
  serifFallback: b64(''),
};
